SELECT * FROM (SELECT SALDO_ACUMULADO AS PICO_PERIODO, DATE_FORMAT(DTNEG, '%d/%m/%Y') AS DATA_PICO FROM (SELECT DTNEG, SUM(CASE WHEN ATUALESTOQUE = 1 THEN PESO_ITEM WHEN ATUALESTOQUE = -1 THEN -PESO_ITEM ELSE 0 END) OVER (ORDER BY DTNEG, AUTO_ID) AS SALDO_ACUMULADO FROM IMP_NOTAS_ARMAZ WHERE CODPARC = :VAR_PARCEIRO_SELECIONADO AND DTNEG <= LAST_DAY(CONCAT(:VAR_MES_SELECIONADO, '-01'))) T WHERE DATE_FORMAT(DTNEG, '%Y-%m') = :VAR_MES_SELECIONADO ORDER BY SALDO_ACUMULADO DESC, DTNEG DESC LIMIT 1) Q1 UNION ALL SELECT * FROM (SELECT IFNULL(SUM(CASE WHEN ATUALESTOQUE = 1 THEN PESO_ITEM WHEN ATUALESTOQUE = -1 THEN -PESO_ITEM ELSE 0 END), 0) AS PICO_PERIODO, 'Saldo Inicial' AS DATA_PICO FROM IMP_NOTAS_ARMAZ WHERE CODPARC = :VAR_PARCEIRO_SELECIONADO AND DTNEG < CONCAT(:VAR_MES_SELECIONADO, '-01')) Q2 LIMIT 1